'use client';

import { useEffect, useId, useRef, useState } from 'react';
import { useReducedMotion } from './use-reduced-motion';
import './token-chip-entry.css';

export interface TokenChipEntryProps {
  value: string[];
  onChange: (value: string[]) => void;
  label: string;
  placeholder?: string;
  className?: string;
}

/**
 * Type a label and press Enter or comma to add it as a chip. Chips pop in
 * and shrink away when removed. Backspace in the empty field removes the
 * last chip; a duplicate is refused with a message and a nudge on the
 * existing chip.
 */
export function TokenChipEntry({
  value,
  onChange,
  label,
  placeholder = 'Add a tag',
  className = '',
}: TokenChipEntryProps) {
  const [draft, setDraft] = useState('');
  const [leaving, setLeaving] = useState<string | null>(null);
  const [dupe, setDupe] = useState<string | null>(null);
  const [message, setMessage] = useState('');
  const input = useRef<HTMLInputElement>(null);
  const list = useRef<HTMLUListElement>(null);
  const focusAfter = useRef<number | 'input' | null>(null);
  const reduced = useReducedMotion();
  const id = useId();

  useEffect(() => {
    const target = focusAfter.current;
    if (target === null) return;
    focusAfter.current = null;
    if (target === 'input') input.current?.focus();
    else
      list.current
        ?.querySelectorAll<HTMLElement>('.mg-chips__remove')
        [target]?.focus();
  }, [value]);

  const commit = () => {
    const text = draft.trim().replace(/,$/, '').trim();
    if (!text) return;
    const existing = value.find((v) => v.toLowerCase() === text.toLowerCase());
    if (existing) {
      setDupe(existing);
      setMessage(`“${existing}” is already added.`);
      return;
    }
    onChange([...value, text]);
    setDraft('');
    setDupe(null);
    setMessage(`Added “${text}”.`);
  };

  const remove = (chip: string, refocus: number | 'input') => {
    const finish = () => {
      setLeaving(null);
      focusAfter.current = refocus;
      onChange(value.filter((v) => v !== chip));
      setMessage(`Removed “${chip}”.`);
    };
    if (reduced) finish();
    else {
      setLeaving(chip);
      window.setTimeout(finish, 180);
    }
  };

  return (
    <div className={`mg-chips ${className}`}>
      <label htmlFor={id} className='mg-chips__label'>
        {label}
      </label>
      <div className='mg-chips__box' onClick={() => input.current?.focus()}>
        <ul ref={list} className='mg-chips__list'>
          {value.map((chip, i) => (
            <li
              key={chip}
              className='mg-chips__chip'
              data-leaving={leaving === chip}
              data-dupe={dupe === chip}
            >
              <span>{chip}</span>
              <button
                type='button'
                className='mg-chips__remove'
                aria-label={`Remove ${chip}`}
                onClick={(event) => {
                  event.stopPropagation();
                  remove(chip, i < value.length - 1 ? i : 'input');
                }}
              >
                <svg
                  width='16'
                  height='16'
                  viewBox='0 0 16 16'
                  aria-hidden='true'
                >
                  <path
                    d='M4 4l8 8M12 4l-8 8'
                    fill='none'
                    stroke='currentColor'
                    strokeWidth='1.75'
                    strokeLinecap='round'
                  />
                </svg>
              </button>
            </li>
          ))}
        </ul>
        <input
          ref={input}
          id={id}
          className='mg-chips__input'
          placeholder={placeholder}
          value={draft}
          aria-describedby={`${id}-help`}
          onChange={(event) => {
            setDupe(null);
            setDraft(event.target.value);
          }}
          onKeyDown={(event) => {
            if (event.key === 'Enter' || event.key === ',') {
              event.preventDefault();
              commit();
            } else if (
              event.key === 'Backspace' &&
              draft === '' &&
              value.length
            ) {
              event.preventDefault();
              remove(value[value.length - 1], 'input');
            }
          }}
        />
      </div>
      <p id={`${id}-help`} className='mg-chips__help'>
        Enter or comma adds a tag. Backspace removes the last one.
      </p>
      <p className='mg-chips__status' role='status'>
        {message}
      </p>
    </div>
  );
}

.mg-chips {
  display: grid;
  gap: 6px;
  color: var(--mg-text, #ffffff);
}

.mg-chips__label {
  font-weight: 700;
}

.mg-chips__box {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
  min-height: 48px;
  padding: 6px;
  border: 1.5px solid var(--mg-line-strong, #474747);
  border-radius: 10px;
  background: #121212;
  cursor: text;
}

.mg-chips__box:focus-within {
  border-color: var(--mg-accent-text, #648aff);
  box-shadow: 0 0 0 3px #303030;
}

.mg-chips__list {
  display: contents;
  margin: 0;
  padding: 0;
  list-style: none;
}

.mg-chips__chip {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  padding-left: 10px;
  border-radius: 999px;
  background: var(--mg-raised, #262626);
  color: #fff;
  font-size: 13px;
  font-weight: 600;
  animation: mg-chips-in 220ms cubic-bezier(0.3, 1.5, 0.5, 1);
}

.mg-chips__chip[data-leaving='true'] {
  animation: mg-chips-out 180ms ease-in forwards;
}

.mg-chips__chip[data-dupe='true'] {
  background: var(--mg-accent, #0047ff);
  animation: mg-chips-nudge 360ms ease;
}

.mg-chips__remove {
  width: 32px;
  height: 32px;
  border: 0;
  border-radius: 50%;
  background: none;
  color: inherit;
  font-size: 16px;
  cursor: pointer;
}

.mg-chips__remove:focus-visible {
  outline: 2px solid var(--mg-accent-text, #648aff);
  outline-offset: -3px;
}

.mg-chips__input {
  flex: 1;
  min-width: 90px;
  height: 34px;
  padding: 0 6px;
  border: 0;
  background: none;
  color: inherit;
  font: inherit;
}

.mg-chips__input:focus {
  outline: none;
}

.mg-chips__help,
.mg-chips__status {
  margin: 0;
  color: #b8b8b8;
  font-size: 12px;
}

.mg-chips__status {
  min-height: 1.3em;
  color: var(--mg-text, #ffffff);
  font-size: 13px;
}

@keyframes mg-chips-in {
  from {
    opacity: 0;
    transform: scale(0.6);
  }
}

@keyframes mg-chips-out {
  to {
    opacity: 0;
    transform: scale(0.6);
  }
}

@keyframes mg-chips-nudge {
  25% {
    transform: translateX(-4px);
  }
  75% {
    transform: translateX(4px);
  }
}

@media (prefers-reduced-motion: reduce) {
  .mg-chips__chip,
  .mg-chips__chip[data-dupe='true'] {
    animation: none;
  }
}

'use client';

import { useEffect, useState } from 'react';

/** True when the user has asked for reduced motion. Follows live changes. */
export function useReducedMotion(): boolean {
  const [reduced, setReduced] = useState(false);
  useEffect(() => {
    const query = window.matchMedia('(prefers-reduced-motion: reduce)');
    const update = () => setReduced(query.matches);
    update();
    query.addEventListener('change', update);
    return () => query.removeEventListener('change', update);
  }, []);
  return reduced;
}
